const CustomRenderer = (args: ComponentProps<typeof KlarnaCheckout> & WithResetQueryCacheArgs) => {
  const queryClient = useQueryClient();

  const [hasResetProvider, setHasResetProvider] = useState(false);

  useEffect(() => {
    queryClient.resetQueries(args.resetQueryKeys[0]);
    setHasResetProvider(true);
  }, [queryClient, args.resetQueryKeys]);

  if (!hasResetProvider) {
    return <div>Resetting query cache...</div>;
  }

  return <KlarnaCheckout {...args} />;
};

const meta = {
  title: "Modules/Klarna Checkout",
  component: KlarnaCheckout,
  render: (args) => (
    <QueryProvider>
      <CustomRenderer {...args} />
    </QueryProvider>
  ),
} satisfies Meta<WithResetQueryCache<typeof KlarnaCheckout>>;

export default meta;

