type ActualCartAndCheckoutArgs = {
  productId: number;
  quantity: number;
  language: Language;
  deliveryType: DeliveryType;
};

const actualBaseUrlCartDev = "https://prs-cdp-dev-webapiproxy.azurewebsites.net/api/v2/glt/";
const actualBaseUrlPaymentDev = "https://prs-cdp-dev-webapiproxy.azurewebsites.net/api/v2/glt/";

const CheckoutServiceWithActualDevApiBaseUrl = createCheckoutService(actualBaseUrlCartDev, actualBaseUrlPaymentDev);

function ActualCartAndCheckoutRenderer(args: ActualCartAndCheckoutArgs) {
  initLabels(args.language);

  const {
    data: cart,
    error: cartError,
    isPending: isLoadingCart,
    mutate,
  } = useAddToCartMutation(undefined, "sv", CheckoutServiceWithActualDevApiBaseUrl);

  const { error: paymentError, isLoading: isLoadingPayment } = useCreatePayment(
    cart?.cartGuid ?? "",
    "sv",
    !!cart,
    undefined,
    { preferredPaymentProvider: "Klarna", redirectOrigin: "https://www.gronalund.com/" },
    CheckoutServiceWithActualDevApiBaseUrl,
  );
  const isLoading = isLoadingCart || isLoadingPayment;
  const error = cartError ?? paymentError;

  return (
    <>
      <PrimaryButton
        label="New cart and checkout!"
        onClick={() => {
          mutate({
            item: {
              productId: args.productId,
              quantity: args.quantity,
              deliveryType: args.deliveryType,
            },
          });
        }}
      />
      <p>Component below 👇</p>
      {isLoading && <p>Loading cart ...</p>}
      {error && <p>Error loading cart: {"message" in error ? error.message : JSON.stringify(error)}</p>}
      {cart && <KlarnaCheckout cartId={cart.cartGuid} checkoutService={CheckoutServiceWithActualDevApiBaseUrl} />}
    </>
  );
}

